[CmdletBinding()]
param([string]$RepoRoot = (Split-Path -Parent $PSScriptRoot))

$ErrorActionPreference = 'Stop'
$resolvedRepoRoot = (Resolve-Path -LiteralPath $RepoRoot).Path
$catalogRoot = Join-Path $resolvedRepoRoot 'vm-packages/builtin/windows'
$packages = @(Get-ChildItem -LiteralPath $catalogRoot -Directory | Sort-Object Name)

function Assert-PackageLifecycle {
    param([bool]$Condition,[string]$Message)
    if (-not $Condition) { throw $Message }
}

Assert-PackageLifecycle -Condition ($packages.Count -eq 36) -Message ("Expected 36 Windows builtin packages; found {0}." -f $packages.Count)
foreach ($directory in @($packages)) {
    $manifestPath = Join-Path $directory.FullName 'package.json'
    $manifest = Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json
    Assert-PackageLifecycle -Condition ([string]$manifest.id -ceq [string]$directory.Name) -Message ("Package id mismatch: {0}" -f $directory.Name)
    Assert-PackageLifecycle -Condition (([string]$manifest.installScript) -ceq 'install.ps1') -Message ("Package '{0}' does not use its Windows installer." -f $directory.Name)
    Assert-PackageLifecycle -Condition ((Test-Path -LiteralPath (Join-Path $directory.FullName 'install.ps1') -PathType Leaf)) -Message ("Package '{0}' has no install.ps1." -f $directory.Name)
    Assert-PackageLifecycle -Condition (([string]$manifest.statusScript) -ceq 'status.ps1') -Message ("Package '{0}' must declare status.ps1." -f $directory.Name)
    Assert-PackageLifecycle -Condition (([string]$manifest.updateScript) -ceq 'update.ps1') -Message ("Package '{0}' must declare update.ps1." -f $directory.Name)
    Assert-PackageLifecycle -Condition (([string]$manifest.uninstallScript) -ceq 'uninstall.ps1') -Message ("Package '{0}' must declare uninstall.ps1." -f $directory.Name)
    Assert-PackageLifecycle -Condition ([string]$manifest.updateStrategy -in @('winget','winget-vscode','choco','npm','choco-self','installer','sysinternals','teams-bootstrapper','anydesk','windscribe')) -Message ("Package '{0}' has an invalid update strategy." -f $directory.Name)
    foreach ($operation in @('status','update','uninstall','repair')) {
        $scriptPath = Join-Path $directory.FullName ("{0}.ps1" -f $operation)
        Assert-PackageLifecycle -Condition (Test-Path -LiteralPath $scriptPath -PathType Leaf) -Message ("Package '{0}' has no {1}.ps1." -f $directory.Name,$operation)
        $scriptText = [string](Get-Content -LiteralPath $scriptPath -Raw)
        Assert-PackageLifecycle -Condition ($scriptText.Contains('CLAGNOS_PACKAGE_SPEC_B64')) -Message ("Package '{0}' {1}.ps1 is missing its package specification input." -f $directory.Name,$operation)
        Assert-PackageLifecycle -Condition ($scriptText -match ("-Action {0}\b" -f $operation)) -Message ("Package '{0}' {1}.ps1 dispatches the wrong lifecycle action." -f $directory.Name,$operation)
        Assert-PackageLifecycle -Condition ($scriptText.Contains('clagnos-package-operations.psm1')) -Message ("Package '{0}' {1}.ps1 must use the shared verified operation helper." -f $directory.Name,$operation)
    }
}

$runtimeText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'modules/commands/package/runtime.ps1') -Raw)
$entryText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'modules/commands/package/entry.ps1') -Raw)
$packageContractText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'modules/commands/package/contract.ps1') -Raw)
$helpText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'modules/core/cli/clagnos-help.ps1') -Raw)
$winrmText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'modules/core/tasks/clagnos-winrm-task-runner.ps1') -Raw)
$appStatePluginText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'modules/core/tasks/clagnos-app-state-plugin.ps1') -Raw)
$operationModuleText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'modules/commands/package/clagnos-package-operations.psm1') -Raw)
$livePackageE2eText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'tests/live-package-lifecycle-e2e.ps1') -Raw)
$uiText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'scripts/clagnos-cli.ps1') -Raw)
$contractText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'modules/commands/package/contract.ps1') -Raw)
$envText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'clagnos.env.example') -Raw)
$benchmarkText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'tools/benchmark-package-transports.ps1') -Raw)
$setupRunnerText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'setup-vc.ps1') -Raw)
$setupVc1ShimText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'setup-vc1.ps1') -Raw)
$setupVc2ShimText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'setup-vc2.ps1') -Raw)
$setupVc1CmdText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'setup-vc1.cmd') -Raw)
$setupVc2CmdText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'setup-vc2.cmd') -Raw)
$removeRunnerText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'remove-vc.ps1') -Raw)
$removeVc1CmdText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'remove-vc1.cmd') -Raw)
$removeVc2CmdText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'remove-vc2.cmd') -Raw)
$componentRuntimeText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'modules/commands/component/runtime.ps1') -Raw)

$null = . (Join-Path $resolvedRepoRoot 'clagnos.ps1')
$allWindowsPackages = @(
    @(Get-ClagnosPackageCatalog -Platform windows -Catalog builtin) +
    @(Get-ClagnosPackageCatalog -Platform windows -Catalog custom)
)
$orderedPackageIds = @((Get-ClagnosPackageDependencyOrder -Packages $allWindowsPackages) | ForEach-Object { [string]$_.Id })
foreach ($dependencyPair in @(
    @('windows-subsystem-linux','docker-desktop'),
    @('nodejs','github-copilot-cli'),
    @('nodejs','google-gemini-cli'),
    @('nodejs','openai-codex-cli')
)) {
    $dependencyIndex = [array]::IndexOf([object[]]$orderedPackageIds,[string]$dependencyPair[0])
    $dependentIndex = [array]::IndexOf([object[]]$orderedPackageIds,[string]$dependencyPair[1])
    Assert-PackageLifecycle -Condition ($dependencyIndex -ge 0 -and $dependentIndex -gt $dependencyIndex) -Message ("Package setup must order '{0}' before '{1}'." -f [string]$dependencyPair[0],[string]$dependencyPair[1])
}
$wingetDependentIds = @('7zip','anydesk','azure-cli','azure-developer-cli','be-my-eyes','codex-app','docker-desktop','google-drive','icloud','itunes','jaws','microsoft-edge','nvda','ollama','onedrive','rclone','visual-studio-code','vlc','whatsapp','windscribe')
$wingetBootstrapIndex = [array]::IndexOf([object[]]$orderedPackageIds,'windows-package-manager')
foreach ($packageId in @($wingetDependentIds)) {
    $packageRow = @($allWindowsPackages | Where-Object { [string]$_.Id -eq [string]$packageId })[0]
    $packageIndex = [array]::IndexOf([object[]]$orderedPackageIds,[string]$packageId)
    Assert-PackageLifecycle -Condition ($null -ne $packageRow -and @($packageRow.PackageTask.DependsOn | Where-Object { [string]$_ -eq 'windows-package-manager' }).Count -eq 1 -and $wingetBootstrapIndex -ge 0 -and $packageIndex -gt $wingetBootstrapIndex) -Message ("WinGet-dependent package '{0}' must wait for the verified Windows Package Manager bootstrap." -f [string]$packageId)
}
$jawsPackage = @($allWindowsPackages | Where-Object { [string]$_.Id -eq 'jaws' })[0]
$generatedRepairScript = New-ClagnosPackageLifecycleScript -Action repair -Package $jawsPackage
$repairTokens = $null
$repairParseErrors = $null
[void][System.Management.Automation.Language.Parser]::ParseInput([string]$generatedRepairScript,[ref]$repairTokens,[ref]$repairParseErrors)
Assert-PackageLifecycle -Condition (@($repairParseErrors).Count -eq 0) -Message 'Generated app-state-backed package repair wrappers must parse before they can run.'
$sevenZipManifest = Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'vm-packages/builtin/windows/7zip/package.json') -Raw | ConvertFrom-Json
Assert-PackageLifecycle -Condition ([string]$sevenZipManifest.statusCheck.kind -eq 'winget' -and [string]$sevenZipManifest.statusCheck.value -eq '7zip.7zip' -and [string]$sevenZipManifest.updateStrategy -eq 'winget' -and [string]$sevenZipManifest.repairStrategy -eq 'winget' -and [string]$sevenZipManifest.uninstall.kind -eq 'winget' -and [bool]$sevenZipManifest.uninstall.allVersions -and $operationModuleText.Contains("'--all-versions'") -and $operationModuleText.Contains('function Test-ClagnosPackageVersionEquivalent')) -Message '7-Zip must use WinGet for consistent detection and lifecycle actions, remove duplicate registered versions, and normalize equivalent numeric version strings.'
$winGetManifest = Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'vm-packages/builtin/windows/windows-package-manager/package.json') -Raw | ConvertFrom-Json
$winGetInstallerText = [string](Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'vm-packages/builtin/windows/windows-package-manager/install.ps1') -Raw)
Assert-PackageLifecycle -Condition ([string]$winGetManifest.statusCheck.kind -eq 'command' -and [string]$winGetManifest.statusCheck.value -eq 'C:\ProgramData\clagnos\tools\winget-x64\winget.exe' -and [int]$winGetManifest.operationTimeoutSeconds.install -eq 300 -and $winGetInstallerText.Contains("C:\ProgramData\clagnos\tools\winget-x64")) -Message 'Windows Package Manager status must verify its stable portable WinGet executable and allow bootstrap to complete within a finite budget.'
$gitManifest = Get-Content -LiteralPath (Join-Path $resolvedRepoRoot 'vm-packages/builtin/windows/git/package.json') -Raw | ConvertFrom-Json
$gitInstallerText = [string](Get-Content -LiteralPath (Join-Path $catalogRoot 'git/install.ps1') -Raw)
Assert-PackageLifecycle -Condition ([string]$gitManifest.uninstall.kind -eq 'choco' -and [string]$gitManifest.uninstall.value -eq 'git' -and [bool]$gitManifest.uninstall.removeDependencies -and $operationModuleText.Contains('--remove-dependencies') -and $operationModuleText.Contains('git.install remained present') -and $gitInstallerText.Contains('function Test-GitChocolateyMetaPackageInstalled') -and $gitInstallerText.Contains('restoring package registration')) -Message 'Git package uninstall must remove Chocolatey meta-package dependencies unattended, and install must restore meta-package registration even when git.install files remain.'
$ffmpegManifest = Get-Content -LiteralPath (Join-Path $catalogRoot 'ffmpeg/package.json') -Raw | ConvertFrom-Json
$ffmpegInstallerText = [string](Get-Content -LiteralPath (Join-Path $catalogRoot 'ffmpeg/install.ps1') -Raw)
$githubCliManifest = Get-Content -LiteralPath (Join-Path $catalogRoot 'github-cli/package.json') -Raw | ConvertFrom-Json
$githubCliInstallerText = [string](Get-Content -LiteralPath (Join-Path $catalogRoot 'github-cli/install.ps1') -Raw)
$azdInstallerText = [string](Get-Content -LiteralPath (Join-Path $catalogRoot 'azure-developer-cli/install.ps1') -Raw)
$dockerInstallerText = [string](Get-Content -LiteralPath (Join-Path $catalogRoot 'docker-desktop/install.ps1') -Raw)
Assert-PackageLifecycle -Condition ([string]$ffmpegManifest.statusCheck.kind -eq 'choco' -and [string]$ffmpegManifest.statusCheck.value -eq 'ffmpeg' -and [string]$ffmpegManifest.statusCheck.executable -eq 'ffmpeg.exe' -and $ffmpegInstallerText.Contains('Get-ClagnosChocolateyPackageExecutableRecord') -and $ffmpegInstallerText.Contains('runnable ffmpeg.exe') -and -not $ffmpegInstallerText.Contains('Get-Command ffmpeg') -and -not $ffmpegInstallerText.Contains('clagnos-package-operations.psm1')) -Message 'FFmpeg must verify the Chocolatey package record and a runnable executable by its absolute package/shim path, without depending on PATH or force-reloading the active lifecycle module.'
Assert-PackageLifecycle -Condition ([string]$githubCliManifest.statusCheck.kind -eq 'choco' -and [string]$githubCliManifest.statusCheck.value -eq 'gh' -and [string]$githubCliManifest.statusCheck.executable -eq 'gh.exe' -and [string]$githubCliManifest.statusCheck.versionArgument -eq '--version' -and @($githubCliManifest.statusCheck.executablePaths).Count -ge 1 -and $githubCliManifest.statusCheck.executablePaths -contains '%ProgramFiles%\GitHub CLI\gh.exe' -and $githubCliInstallerText.Contains('Get-ClagnosChocolateyPackageExecutableRecord') -and $githubCliInstallerText.Contains("-VersionArgument '--version'") -and $githubCliInstallerText.Contains('-AdditionalPaths $ghExecutablePaths') -and -not $githubCliInstallerText.Contains('Get-Command gh -ErrorAction SilentlyContinue') -and -not $githubCliInstallerText.Contains('clagnos-package-operations.psm1')) -Message 'GitHub CLI must resolve its vendor executable path and use its declared --version check so stale WinRM PATH cannot produce a false install failure.'
Assert-PackageLifecycle -Condition ($azdInstallerText.Contains('function Resolve-AzdExecutablePath') -and $azdInstallerText.Contains('LocalApplicationData') -and $azdInstallerText.Contains('Azure Dev CLI\azd.exe') -and $azdInstallerText.Contains('& $azdPath version') -and -not $azdInstallerText.Contains('if (-not (Get-Command azd -ErrorAction SilentlyContinue))')) -Message 'Azure Developer CLI must verify azd through its resolved executable path when PATH has not refreshed in the current WinRM process.'
Assert-PackageLifecycle -Condition ($dockerInstallerText.Contains('function Resolve-DockerExePath') -and $dockerInstallerText.Contains('Docker\resources\bin\docker.exe') -and $dockerInstallerText.Contains('Invoke-ProcessWithTimeout -Label "docker --version"') -and -not $dockerInstallerText.Contains('if (-not (Get-Command docker -ErrorAction SilentlyContinue))')) -Message 'Docker Desktop must validate docker --version through its resolved executable path instead of failing solely because the process PATH is stale.'
Assert-PackageLifecycle -Condition ($operationModuleText.Contains('function Get-ClagnosChocolateyPackageExecutableRecord') -and $operationModuleText.Contains('$status = ''installed-drifted''') -and $operationModuleText.Contains('Get-ChildItem -LiteralPath $toolsRoot -Filter $ExecutableName -File -Recurse') -and $runtimeText.Contains('statusCheck.executable') -and $runtimeText.Contains('Get-ClagnosChocolateyPackageExecutableRecord')) -Message 'Chocolatey package status and lifecycle postconditions must share the executable-aware health check, classify missing/broken registered executables as drifted, and treat unregistered leftovers as unknown.'
Assert-PackageLifecycle -Condition ($operationModuleText.Contains('GetFileNameWithoutExtension($ExecutableName)') -and $operationModuleText.Contains('$versionPattern')) -Message 'Chocolatey executable health checks must validate the matching command name (for example ffmpeg or gh), not assume FFmpeg for every package.'

Assert-PackageLifecycle -Condition ($runtimeText.Contains("'install','repair','update','uninstall'")) -Message 'Package runtime must route install, repair, update, and uninstall as separate actions.'
Assert-PackageLifecycle -Condition ($runtimeText.Contains('function Restart-ClagnosPackageVmForPendingReboot') -and $runtimeText.Contains('[bool]$uninstallRecord.rebootRequired') -and $livePackageE2eText.Contains('[bool]$record.rebootRequired') -and $livePackageE2eText.Contains('packageRequestedRebootCount') -and $livePackageE2eText.Contains('$lastPackageStatusSnapshot')) -Message 'A verified package uninstall that requests a reboot must restart the VM through the shared do command and wait for the configured guest transport before continuing package setup or lifecycle verification; filtered runs reuse their captured final status instead of repeating the same remote request.'
Assert-PackageLifecycle -Condition ($operationModuleText.Contains('$chocoUninstallExitCode -eq 3010') -and $operationModuleText.Contains('Chocolatey uninstall requested a reboot') -and $operationModuleText.Contains('The package vendor requested a reboot (exit code 3010)')) -Message 'Chocolatey uninstall exit 3010 must be surfaced as a verified package reboot request so reinstall and the live E2E runner can restart the VM before the next installer phase.'
Assert-PackageLifecycle -Condition ($operationModuleText.Contains('function Invoke-ClagnosNpmPackageLifecycleCommand') -and $operationModuleText.Contains('$ErrorActionPreference = ''Continue''') -and $operationModuleText.Contains('$nativeOutput = @(& $command.Source @Arguments 2>&1)') -and $operationModuleText.Contains('InstallScriptPolicyWarning = [bool]$policyWarning') -and $operationModuleText.Contains('unapproved dependency install scripts blocked')) -Message 'npm stderr policy warnings must be captured without becoming terminating PowerShell errors, and unapproved install scripts must remain blocked.'
Assert-PackageLifecycle -Condition ($runtimeText.Contains('already installed') -and $runtimeText.Contains('update was not run')) -Message 'Package install/update must not collapse into one operation.'
Assert-PackageLifecycle -Condition ($runtimeText.Contains('no install operation was run') -and $runtimeText.Contains("'reinstall'") -and $runtimeText.Contains('reinstall phase 1/2') -and $runtimeText.Contains('reinstall phase 2/2')) -Message 'Install on an installed package must be a no-op, and reinstall must verify uninstall before a fresh install.'
foreach ($directory in @($packages)) {
    $packageManifest = Get-Content -LiteralPath (Join-Path $directory.FullName 'package.json') -Raw | ConvertFrom-Json
    Assert-PackageLifecycle -Condition ($null -ne $packageManifest.operationTimeoutSeconds -and [int]$packageManifest.operationTimeoutSeconds.status -ge 30 -and [int]$packageManifest.operationTimeoutSeconds.install -ge 30 -and [int]$packageManifest.operationTimeoutSeconds.repair -ge 30 -and [int]$packageManifest.operationTimeoutSeconds.update -ge 30 -and [int]$packageManifest.operationTimeoutSeconds.uninstall -ge 30 -and [int]$packageManifest.operationTimeoutSeconds.reinstall -ge 30) -Message ("Package '{0}' must define finite operation-specific lifecycle timeouts." -f [string]$packageManifest.id)
    $overMaximum = @($packageManifest.operationTimeoutSeconds.PSObject.Properties | Where-Object { [int]$_.Value -gt 480 })
    $overStandardWithoutEvidence = @($packageManifest.operationTimeoutSeconds.PSObject.Properties | Where-Object { [int]$_.Value -gt 360 -and ($null -eq $packageManifest.operationTimeoutEvidence -or $null -eq $packageManifest.operationTimeoutEvidence.PSObject.Properties[$_.Name]) })
    Assert-PackageLifecycle -Condition ($overMaximum.Count -eq 0 -and $overStandardWithoutEvidence.Count -eq 0) -Message ("Package '{0}' operation budgets must not exceed 480 seconds, and budgets over 360 seconds require measured evidence." -f [string]$packageManifest.id)
    Assert-PackageLifecycle -Condition ([string]$packageManifest.repairStrategy -in @('winget','winget-prefix','winget-vscode','google-drive-verify','wsl-msi','choco','npm','choco-self','appx','startup','installer-verify','sysinternals','windscribe','jaws')) -Message ("Package '{0}' must declare an explicit safe repair provider." -f [string]$packageManifest.id)
    if ([string]$packageManifest.statusCheck.kind -in @('appx','store-state')) {
        Assert-PackageLifecycle -Condition ([string]$packageManifest.repairStrategy -eq 'installer-verify') -Message ("Store package '{0}' must use its version-preserving installer health path for same-version repair over WinRM." -f [string]$packageManifest.id)
    }
}
Assert-PackageLifecycle -Condition ($runtimeText.Contains('New-ClagnosPackageRepairWithAppStateBackupScript') -and $runtimeText.Contains('package-repair-backups') -and $runtimeText.Contains('VerifyMismatchCount')) -Message 'Same-version package repair must snapshot app-state, restore and verify it, and retain an emergency backup only after a failed restore.'
Assert-PackageLifecycle -Condition ($operationModuleText.Contains('--version ([string]$record.Version)') -and $operationModuleText.Contains('same-version repair')) -Message 'Package repair must pin the detected version and refuse a vendor upgrade.'
 $nvdaManifest = Get-Content -LiteralPath (Join-Path $catalogRoot 'nvda/package.json') -Raw | ConvertFrom-Json
Assert-PackageLifecycle -Condition ([string]$nvdaManifest.uninstall.kind -eq 'nvda' -and [string]$nvdaManifest.uninstall.value -eq 'C:\Program Files\NVDA\uninstall.exe' -and $runtimeText.Contains("[string]`$uninstall.kind -eq 'nvda'") -and $operationModuleText.Contains("'nvda' {") -and $operationModuleText.Contains("ArgumentList @('/S')") -and $operationModuleText.Contains('signed NVDA vendor uninstaller') -and $operationModuleText.Contains('application files and uninstall registry entry are absent')) -Message 'NVDA uninstall must stop package processes, run the signed vendor /S uninstaller with a finite deadline, and verify executable and uninstall registry absence.'
Assert-PackageLifecycle -Condition ([string]$nvdaManifest.repairStrategy -eq 'winget-prefix' -and $operationModuleText.Contains("'winget-prefix' {") -and $operationModuleText.Contains("(?<release>\d{4}\.\d+)(?:\.\d+)*") -and $operationModuleText.Contains('could not be verified for installed product version') -and $operationModuleText.Contains('NVDA same-release repair')) -Message 'NVDA repair must map its product build version to an exact verified WinGet release and verify the installed product version remains unchanged.'
$vscodeManifest = Get-Content -LiteralPath (Join-Path $catalogRoot 'visual-studio-code/package.json') -Raw | ConvertFrom-Json
Assert-PackageLifecycle -Condition ([string]$vscodeManifest.repairStrategy -eq 'winget-vscode' -and $operationModuleText.Contains("'winget-vscode' {") -and $operationModuleText.Contains('Installer Url:') -and $operationModuleText.Contains('payloadVersion') -and $operationModuleText.Contains('--scope user') -and $operationModuleText.Contains('no repair mutation was attempted')) -Message 'Visual Studio Code repair must verify that the exact WinGet installer payload matches its installed user version before running a bounded same-version repair.'
Assert-PackageLifecycle -Condition ([string]$vscodeManifest.updateStrategy -eq 'winget-vscode' -and [string]$vscodeManifest.updatePackageId -eq 'Microsoft.VisualStudioCode' -and $operationModuleText.Contains('No applicable upgrade; the verified WinGet installer payload') -and $operationModuleText.Contains('not newer than installed Visual Studio Code')) -Message 'Visual Studio Code update must compare its actual signed installer payload version before upgrading, so a newer catalog label cannot trigger a downgrade.'
Assert-PackageLifecycle -Condition ([int]$vscodeManifest.operationTimeoutSeconds.install -ge 240 -and [int]$vscodeManifest.operationTimeoutSeconds.repair -ge 240 -and [int]$vscodeManifest.operationTimeoutSeconds.update -ge 240) -Message 'Visual Studio Code lifecycle budgets must cover the observed installer plus app-state verification time.'
$chromeManifest = Get-Content -LiteralPath (Join-Path $catalogRoot 'google-chrome/package.json') -Raw | ConvertFrom-Json
Assert-PackageLifecycle -Condition ([int]$chromeManifest.operationTimeoutSeconds.install -ge 240 -and [int]$chromeManifest.operationTimeoutSeconds.repair -ge 240 -and [int]$chromeManifest.operationTimeoutSeconds.update -ge 240) -Message 'Google Chrome lifecycle budgets must cover the measured guest install activity instead of stopping the active installer early.'
$wslManifest = Get-Content -LiteralPath (Join-Path $catalogRoot 'windows-subsystem-linux/package.json') -Raw | ConvertFrom-Json
$wslInstallerText = [string](Get-Content -LiteralPath (Join-Path $catalogRoot 'windows-subsystem-linux/install.ps1') -Raw)
Assert-PackageLifecycle -Condition ([string]$wslManifest.statusCheck.kind -eq 'wsl' -and [string]$wslManifest.uninstall.kind -eq 'wsl' -and [string]$wslManifest.repairStrategy -eq 'wsl-msi' -and $operationModuleText.Contains('function Get-ClagnosWslPackageRecord') -and $operationModuleText.Contains("'wsl' {") -and $operationModuleText.Contains('WSL has registered distributions; uninstall was refused to protect their data') -and $operationModuleText.Contains('msiexec.exe') -and $operationModuleText.Contains('REINSTALL=ALL REINSTALLMODE=vomus') -and $wslInstallerText.Contains('api.github.com/repos/microsoft/WSL/releases/latest') -and $wslInstallerText.Contains('Get-FileHash') -and $wslInstallerText.Contains('install signed WSL MSI') -and $wslInstallerText.Contains('Windows Installer returned 1') -and -not $wslInstallerText.Contains('Wait-ClagnosUserInteractiveDesktopReady')) -Message 'WSL package lifecycle must detect, install, repair, and remove its MSI package; protect registered distribution data; and use a hash-verified official MSI without a desktop session.'
Assert-PackageLifecycle -Condition ($operationModuleText.Contains('function Resolve-ClagnosWingetExecutable') -and $operationModuleText.Contains("Get-AppxPackage -AllUsers -Name 'Microsoft.DesktopAppInstaller'") -and $operationModuleText.Contains('Initialize-ClagnosWingetCommandPath')) -Message 'Winget package detection and installers must resolve the App Installer payload even when the per-user WindowsApps alias is absent.'
Assert-PackageLifecycle -Condition ($runtimeText.Contains('UpdatePackageId = [string]$updatePackageId') -and $runtimeText.Contains('updatePackageId = [string]$Package.UpdatePackageId') -and $operationModuleText.Contains('$spec.updatePackageId')) -Message 'A package update provider identity may be separate from the package detection value, and must be carried into the remote lifecycle command.'
Assert-PackageLifecycle -Condition ($runtimeText.Contains('`$npmModulesRoot = Join-Path') -and $operationModuleText.Contains('$npmModulesRoot = Join-Path') -and -not $runtimeText.Contains('list --global --depth=0 --json')) -Message 'Npm package status must inspect the managed global package directory without failing the WinRM task when npm has an empty global inventory.'
Assert-PackageLifecycle -Condition ($winrmText.Contains('Add-ClagnosPackageTrustedHost') -and $winrmText.Contains('Invoke-Command') -and $winrmText.Contains('Copy-Item') -and $winrmText.Contains('Get-ClagnosPackageGuestTelemetry') -and $winrmText.Contains('ProcessIoBytes') -and $winrmText.Contains('no guest CPU, network, disk, memory, or output progress for 60s') -and $winrmText.Contains('retrying once')) -Message 'The WinRM package runner must stream output, sample guest activity, enforce an idle threshold, and bound one retry.'
Assert-PackageLifecycle -Condition ($winrmText.Contains('Stop-Job -Job $job -ErrorAction') -and -not $winrmText.Contains('Stop-Job -Job $job -Force')) -Message 'WinRM timeout cleanup must use Stop-Job parameters supported by Windows PowerShell 5.1.'
Assert-PackageLifecycle -Condition ($appStatePluginText.Contains('$Transport -eq ''ssh'' -and (') -and $appStatePluginText.Contains('$Transport -eq ''winrm''')) -Message 'Windows app-state replay must not require SSH credentials when a WinRM session is supplied.'
Assert-PackageLifecycle -Condition ($winrmText.Contains("Get-ClagnosPackageTransport") -or $runtimeText.Contains("Get-ClagnosPackageTransport")) -Message 'Package transport selection must be implemented.'
Assert-PackageLifecycle -Condition ($operationModuleText.Contains('CLAGNOS_PACKAGE_RESULT:') -and $operationModuleText.Contains('Uninstall did not verify') -and $operationModuleText.Contains('durationSeconds') -and $operationModuleText.Contains('Export-ModuleMember -Function Invoke-ClagnosPackageLifecycle') -and $operationModuleText.Contains('Test-ClagnosJawsLogonScreenStartup')) -Message 'Package scripts must emit timed structured results, verify uninstall, and validate JAWS logon-screen startup.'
Assert-PackageLifecycle -Condition ($operationModuleText.Contains('jfw.exe') -and $operationModuleText.Contains('JAWS update file copied and verified')) -Message 'JAWS update must close the application, apply update-files, and verify the copied payload.'
 $sysinternalsManifest = Get-Content -LiteralPath (Join-Path $catalogRoot 'sysinternals/package.json') -Raw | ConvertFrom-Json
 $sysinternalsInstallText = [string](Get-Content -LiteralPath (Join-Path $catalogRoot 'sysinternals/install.ps1') -Raw)
Assert-PackageLifecycle -Condition ([string]$sysinternalsManifest.statusCheck.kind -eq 'sysinternals' -and [string]$sysinternalsManifest.uninstall.kind -eq 'sysinternals' -and [string]$sysinternalsManifest.repairStrategy -eq 'sysinternals' -and [string]$sysinternalsManifest.updateStrategy -eq 'sysinternals' -and $sysinternalsInstallText.Contains('Install-ClagnosSysinternalsPackage') -and -not $sysinternalsInstallText.Contains('--ignore-checksums') -and $operationModuleText.Contains('Get-AuthenticodeSignature') -and $operationModuleText.Contains('download.sysinternals.com/files/SysinternalsSuite.zip') -and $operationModuleText.Contains('Get-ClagnosSysinternalsPackageRecord')) -Message 'Sysinternals lifecycle must use the official Microsoft payload with Authenticode verification and no checksum bypass.'
